from functools import wraps
from flask import request, jsonify
import os

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization')
        if not auth_header or not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Unauthorized'}), 401

        token = auth_header.split(' ')[1]
        if token == "invalid":
            return jsonify({'error': 'Invalid token'}), 401

        request.user = {'id': '123', 'email': 'test@example.com'}
        return f(*args, **kwargs)
    return decorated

from flask import Blueprint, request, jsonify
from services.core.shared.database import get_db
from services.core.shared.middleware import require_auth

auth_bp = Blueprint('auth', __name__)

@auth_bp.route('/api/auth/login', methods=['POST'])
def login():
    data = request.json
    return jsonify({'token': 'mock-jwt-token', 'user': {'email': data.get('email')}})

@auth_bp.route('/api/auth/register', methods=['POST'])
def register():
    data = request.json
    return jsonify({'message': 'User registered successfully', 'user': {'email': data.get('email')}}), 201

@auth_bp.route('/api/auth/logout', methods=['POST'])
@require_auth
def logout():
    return jsonify({'message': 'Logged out successfully'})

@auth_bp.route('/api/me', methods=['GET'])
@require_auth
def get_current_user():
    return jsonify({'user': request.user})

